    // spec function: number of decimal digits of x (for x >= 1 it is >= 1)
    #[verus::spec]
    fn num_len(x: i32) -> u64 {
        if x <= 0 {
            0
        } else {
            1 + num_len(x / 10)
        }
    }

    // spec function: the closed‐form total button‐presses up to and including x
    #[verus::spec]
    fn score_spec(x: i32) -> u64 {
        // digit d = last digit of x
        let d = (x % 10) as u64;
        // k = length of x in digits
        let k = num_len(x);
        // for each smaller digit we have 1+2+3+4 = 10 presses,
        // and within the same digit we sum lengths 1..(k-1), then + k for x itself
        (d - 1) * 10 + k * (k - 1) / 2 + k
    }

    pub fn solve(x: i32) -> i32 {
        // input guaranteed 1 ≤ x ≤ 9999 and that x is of the boring form ddd…d
        requires(x >= 1 && x <= 9999);
        // our result must match the spec
        ensures(|res: i32| (res as u64) == score_spec(x));

        // first compute k = number of digits of x
        let mut y = x;
        let mut k: i32 = 0;
        while y > 0 {
            // y remains between 0 and x
            invariant(y >= 0 && y <= x);
            // k remains in the small range 0..=4
            invariant(0 <= k && k <= 4);
            // crucial linking invariant:
            //   k + num_len(y) == num_len(x)
            // initially y=x,k=0 so 0+num_len(x)==num_len(x),
            // each iteration peels off one digit of y and increments k.
            invariant((k as u64) + num_len(y) == num_len(x));

            k += 1;
            y /= 10;
        }
        // now y == 0, so from the invariant k == num_len(x)
        assert(y == 0);
        assert((k as u64) == num_len(x));

        // extract the repeated digit d
        let d = x % 10;
        // sum of presses for all smaller digits = (d-1) * (1+2+3+4) = (d-1)*10
        let prev = (d - 1) * 10;
        // sum of presses for the same digit but shorter lengths 1..(k-1) = k*(k-1)/2
        let curr = k * (k - 1) / 2;
        // plus k presses to type x itself
        let res = prev + curr + k;
        res
    }

